'use client';

export default function StatsCard({ label, value, sub, icon, iconBg, valueColor, trend, trendUp }) {
  return (
    <div className="stat-card">
      <div className="stat-card-header">
        <div>
          <div className="stat-card-label">{label}</div>
        </div>
        <div
          className="stat-card-icon"
          style={{ background: iconBg || 'rgba(34,197,94,0.1)', border: `1px solid ${iconBg ? iconBg.replace('0.1', '0.3') : 'rgba(34,197,94,0.2)'}` }}
        >
          {icon}
        </div>
      </div>

      <div
        className="stat-card-value"
        style={{ color: valueColor || '#f1f5f9' }}
      >
        {value}
      </div>

      <div className="stat-card-sub">{sub}</div>

      {trend && (
        <div
          className="stat-card-trend"
          style={{
            background: trendUp ? 'rgba(239,68,68,0.1)' : 'rgba(34,197,94,0.1)',
            color: trendUp ? '#ef4444' : '#22c55e',
          }}
        >
          <span>{trendUp ? '▲' : '▼'}</span>
          {trend}
        </div>
      )}
    </div>
  );
}
